def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    threat_bids = []
    urgent_opponents = 0
    rich_opponents = 0

    for opp in alive_opponents:
        if opp.get('budget', 0) >= DAILY_SALARY * 4:
            rich_opponents += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opponents += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('budget', 0) > 0:
                threat_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    highest_threat = max(threat_bids) if threat_bids else highest_prev

    tight_supply = supply <= 17
    medium_supply = supply <= 20

    if hp <= 2 or no_water_days >= 2:
        bid = max(DAILY_SALARY * 0.95, highest_threat + 2.5)
    elif hp <= 4 or no_water_days >= 1:
        if tight_supply:
            bid = max(DAILY_SALARY * 0.88, highest_threat + 2.0)
        else:
            bid = max(DAILY_SALARY * 0.72, avg_prev + 2.0)
    else:
        if tight_supply:
            bid = max(DAILY_SALARY * 0.82, highest_threat + 1.5)
        elif medium_supply:
            bid = max(DAILY_SALARY * 0.62, avg_prev + 1.0)
        else:
            bid = DAILY_SALARY * 0.42

    if rich_opponents >= 2:
        bid += 4.0
    elif rich_opponents == 1:
        bid += 2.0

    if urgent_opponents >= 2 and tight_supply:
        bid += 5.0
    elif urgent_opponents >= 1 and medium_supply:
        bid += 2.5

    if day >= 8 and hp > 4:
        bid *= 0.94

    cap = budget
    if hp > 4 and no_water_days == 0:
        cap = min(cap, DAILY_SALARY * 1.15)
    else:
        cap = min(cap, DAILY_SALARY * 1.4)

    if budget < DAILY_SALARY * 0.6 and hp > 3 and no_water_days == 0:
        bid = min(bid, budget * 0.75)

    bid = max(0.0, min(bid, cap))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents and their yesterday bids
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            prev = o.get('previous_trace', {}) or {}
            bid = prev.get('bid', None)
            alive_opps.append((oid, o, bid))

    if not alive_opps:
        # No competition: conserve budget
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for oid, o, bid in alive_opps:
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    # Estimate how aggressive the field was
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    # Base bid depends on our hp
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])

    # If our hp is low, we must buy more water (higher bid)
    if hp <= 2:
        base = DAILY_SALARY * 0.85
    elif hp <= 4:
        base = DAILY_SALARY * 0.65
    else:
        base = DAILY_SALARY * 0.52

    # If Cindy (the consistent survivor) was very aggressive yesterday, slightly increase
    cindy_prev_bid = None
    if 'Cindy' in opponents_status and opponents_status['Cindy'].get('alive', False):
        prev = opponents_status['Cindy'].get('previous_trace', {}) or {}
        c_bid = prev.get('bid', None)
        if c_bid is not None:
            try:
                cindy_prev_bid = float(c_bid)
            except Exception:
                cindy_prev_bid = None

    # Supply pressure: higher supply reduces need to overbid
    # Normalize supply into [0,1]
    supply_norm = (supply - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
    if supply_norm < 0.0:
        supply_norm = 0.0
    if supply_norm > 1.0:
        supply_norm = 1.0

    # If supply is high, we can bid a bit less; if low, bid a bit more
    supply_adjust = 1.0 + (0.08 * (0.5 - supply_norm))  # +/- ~4%

    # Aggression adjustment based on yesterday
    aggression_adjust = 1.0
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        aggression_adjust = 1.10
    elif highest_prev_bid >= DAILY_SALARY * 0.65:
        aggression_adjust = 1.05
    else:
        aggression_adjust = 0.98

    if cindy_prev_bid is not None and cindy_prev_bid >= DAILY_SALARY * 0.85:
        aggression_adjust = max(aggression_adjust, 1.12)

    bid = base * supply_adjust * aggression_adjust

    # Never exceed budget
    bid = min(bid, budget)

    # Safety floor/ceiling to avoid extreme bids
    min_bid = 1.0
    max_bid = DAILY_SALARY * 0.95
    if bid < min_bid:
        bid = min_bid
    if bid > max_bid:
        bid = max_bid

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
